  (id, question_id, version, state, text, explanation, category_id, country_scope, difficulty, age_rating, tags, language, sources, content_hash, published_at)
values
  ('b735e857-f341-5e31-9a9f-1732706cd608', '283252ac-4624-5de8-bdc2-39d43f58c24b', 1, 'approved', 'Tagine is both a slow-cooked stew and the clay pot it is cooked in. It is most associated with which country?', 'The tagine, with its cone-shaped lid, is a signature of Moroccan and wider North African cooking.', 'culture', array['MA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Tajine","url":"https://en.wikipedia.org/wiki/Tajine"}]'::jsonb, 'cecf6d76d520a4fbf721ec7847b96877711f4c7418d1e96f92253bff5c46af27', now()),
  ('d4369db6-16b0-5234-85a5-2018f708c9a8', '6c916d31-eeda-5032-bb57-2a5842fd956f', 1, 'approved', 'Peri-peri (piri-piri) chilli sauce is most closely associated with the cooking of which country?', 'Peri-peri sauce developed in Mozambique from the African bird’s eye chilli and Portuguese cooking.', 'culture', array['MZ']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Piri piri","url":"https://en.wikipedia.org/wiki/Piri_piri"}]'::jsonb, '6e9de1a2360282098356da1671fd7be4a3db50e58e7154ea58b04d02ab849016', now()),
  ('cadd81e2-e95d-5c19-b147-a3faeeb9320a', '204c688c-be7c-5c00-aba8-cc1594478416', 1, 'approved', 'The Argungu Fishing Festival is held in which country?', 'The Argungu Fishing Festival takes place in Kebbi State, north-western Nigeria.', 'culture', array['NG']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Argungu Fishing Festival","url":"https://en.wikipedia.org/wiki/Argungu_Fishing_Festival"}]'::jsonb, '03d4ccc8981b345079dfd38cb6b1e1969f61db8f9dc2f31b3fad8be48068355e', now()),
  ('7f8b484a-c81c-5e3c-8873-de809653369a', '1416101d-79b9-5e19-a375-71dc5f16ffa1', 1, 'approved', 'Bobotie, a spiced minced-meat dish baked with an egg topping, is associated with which country?', 'Bobotie is a South African dish with roots in Cape Malay cooking.', 'culture', array['ZA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Bobotie","url":"https://en.wikipedia.org/wiki/Bobotie"}]'::jsonb, '27bad8acbaae6549edcfe5ab196c259a91c865af1bce73debf177a4d4b755549', now()),
  ('2cf349a6-eac4-5bd8-8776-07309e40ce04', '697904db-0c2d-51fe-a39f-7486b86c00d4', 1, 'approved', 'The Ndebele people, famous for brightly painted geometric house murals, live mainly in which country?', 'Southern Ndebele women are renowned for bold geometric wall paintings, especially in Mpumalanga, South Africa.', 'culture', array['ZA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Southern Ndebele people","url":"https://en.wikipedia.org/wiki/Southern_Ndebele_people"}]'::jsonb, '20304cfdf352b8fa0adbc748e63503a0aac86e14961ebde218319bab9c0be99a', now()),
  ('fd79b664-46a4-574c-9e02-55d32fbca1f3', '59553aa7-48ad-5e08-befd-e10cf9f56ded', 1, 'approved', 'The Himba people, who coat their skin and hair with red ochre paste (otjize), live mainly in which country?', 'The Himba live mainly in the Kunene region of northern Namibia, with smaller communities in Angola.', 'culture', array['NA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Himba people","url":"https://en.wikipedia.org/wiki/Himba_people"}]'::jsonb, 'fe3732c9300f1490a707a52268ac902c121c6c2a0bae9e161761c6e2aedf130b', now()),
  ('6427c249-46e4-586a-a569-b3fa070f2800', 'ce58df27-9302-5031-ae35-e014200997de', 1, 'approved', 'The Gerewol, a courtship festival where young men compete in beauty contests, is held by which people?', 'The Wodaabe, a Fulani pastoralist group of Niger and Chad, hold the Gerewol at the end of the rainy season.', 'culture', array['NE', 'TD']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Wodaabe","url":"https://en.wikipedia.org/wiki/Wodaabe"}]'::jsonb, 'ac850a773403344331cff0efc736c2239e66d2d3e58920a855c882719ac92986', now()),
  ('b24ce013-67cf-5dea-833b-72db09ee1d4b', '214401fa-e503-5a32-8af0-cc0a0ce0b16e', 1, 'approved', 'The Dogon people, known for cliffside villages on the Bandiagara Escarpment, live in which country?', 'The Dogon live in central Mali; the Cliff of Bandiagara is a UNESCO World Heritage Site.', 'culture', array['ML']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Dogon people","url":"https://en.wikipedia.org/wiki/Dogon_people"}]'::jsonb, 'f0420d358aacf5d6c3afc8f38a79d216c7972217a09bd9b7f74c7531868c736c', now()),
  ('398be31c-0ae8-5e28-8d4f-5081c9bbf0e5', 'ea961f5b-d653-53e6-99b8-1ade9cc90598', 1, 'approved', 'Which country made the Vodun (Voodoo) festival a national holiday every 10 January?', 'Benin celebrates Fête du Vodoun on 10 January, with major events in Ouidah. Vodun originated in this region.', 'culture', array['BJ']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: West African Vodun","url":"https://en.wikipedia.org/wiki/West_African_Vodun"}]'::jsonb, '6d95c112abc31c6425190320ad2baf12fb844072b50be33543aa6093fae5d0a3', now()),
  ('45d8761f-b98d-5cd4-a5a1-4b723073d5a0', 'a2e9d08d-56bb-53de-8f13-ae55759584fe', 1, 'approved', 'Which language is the most widely spoken first language in South Africa?', 'isiZulu is the first language of about a quarter of South Africans, more than any other language.', 'languages', array['ZA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Zulu language","url":"https://en.wikipedia.org/wiki/Zulu_language"}]'::jsonb, '6df607a2dec8ce6548d1fe4074083d33b1f7c43fb635fef04c67a5da569b6ae6', now()),
  ('ad628d83-d51a-54a2-a52f-00b7e0e18b4f', 'aa8394d3-26ea-5d3a-894a-2aae9ae1b340', 1, 'approved', 'Hausa is widely spoken in northern Nigeria and which other country?', 'Hausa is a major language of northern Nigeria and southern Niger, and a lingua franca across much of West Africa.', 'languages', array['NG', 'NE']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Hausa language","url":"https://en.wikipedia.org/wiki/Hausa_language"}]'::jsonb, '6e0acd697dca6ee5422ca755d258d377c7b5b848d8dfceb1e5f5c0dc3546a6cd', now()),
  ('03640416-9f8c-506e-ac08-e213ca192423', 'dd7d9ea2-63f7-58eb-8278-e409214532b7', 1, 'approved', 'Arabic is the main official language of which of these countries?', 'Arabic is Egypt’s official language; Egyptian Arabic is the most widely spoken variety of Arabic.', 'languages', array['EG']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Egyptian Arabic","url":"https://en.wikipedia.org/wiki/Egyptian_Arabic"}]'::jsonb, 'cb0332a7101d802629373830a9a5503bdf652cf47ea5984325b1c3e8298be1e1', now()),
  ('1b415ef8-f10c-5b7e-8f0e-0bc4551162b1', '583dc892-8357-571d-ad4d-9ac5c6ea32fa', 1, 'approved', 'Which language, descended from Dutch, developed in South Africa?', 'Afrikaans grew out of the Dutch spoken in the Cape Colony and is one of South Africa’s official languages.', 'languages', array['ZA', 'NA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Afrikaans","url":"https://en.wikipedia.org/wiki/Afrikaans"}]'::jsonb, 'bba353198948c7cf7b39b0177480211bef4cbce2a5e3f9174ebe9fcf6d71dad2', now()),
  ('12b0de15-7763-53dd-86c2-777e34bf8bf5', '7551de48-a6e3-53e8-917e-7e145a7a3b78', 1, 'approved', 'Wolof is the most widely spoken language in which country?', 'Wolof is spoken by most Senegalese, as a first or second language, and also in The Gambia.', 'languages', array['SN']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Wolof language","url":"https://en.wikipedia.org/wiki/Wolof_language"}]'::jsonb, '5e3c44ffd768a1171bff65a03f73d5f970c5acb74511543c3abae0a4e8f6c8b5', now()),
  ('92a98dfe-c092-5a62-a2e6-54955fe3ddb6', '25187670-d896-5ad2-9360-ca37d0f9ca2a', 1, 'approved', 'Which of these languages is written in the Ge’ez (Ethiopic) script?', 'Amharic uses the Ge’ez script, also called Ethiopic or Fidel. Somali, Hausa and Kiswahili are written in the Latin alphabet.', 'languages', array['ET']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Geʽez script","url":"https://en.wikipedia.org/wiki/Ge%CA%BDez_script"}]'::jsonb, '2b92d342adc6f5215bb5b8700ba2ea9765c26d35db88dc34c4603517e81989cb', now()),
  ('bac2acf4-f623-5f7a-9b0b-252796d8cc1b', '3bbc1a66-72fb-59f0-a3f1-cc34a61e21a7', 1, 'approved', 'isiXhosa is well known for which distinctive kind of sound?', 'isiXhosa has a large set of click consonants, written with the letters c, q and x.', 'languages', array['ZA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Xhosa language","url":"https://en.wikipedia.org/wiki/Xhosa_language"}]'::jsonb, '68835538b6e00e4800b97cd2e96b39f6c6db66ec20d249138ccc96fd77b2784c', now()),
  ('8c4f03ad-8d6b-594d-bedf-6ef64a023152', '7bd7bdc9-9e74-54f2-8000-ccaed78dc066', 1, 'approved', 'Kiswahili, isiZulu, Shona and Kikuyu all belong to which large group of languages?', 'They are Bantu languages, a branch of the Niger–Congo family spoken across central, eastern and southern Africa.', 'languages', array['AFRICA']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Bantu languages","url":"https://en.wikipedia.org/wiki/Bantu_languages"}]'::jsonb, '2551585d7d8e7b0ddaafbb77be62dda01fe2ff443960b2ad0c1a3c61647518a2', now()),
  ('24cfff49-a096-56a4-80cc-1d90351387b3', 'ca9d55e4-eb64-5f89-a76b-8b73805ce2da', 1, 'approved', 'Malagasy, the national language of Madagascar, is most closely related to languages from which region?', 'Malagasy is an Austronesian language; its closest relatives are the Barito languages of southern Borneo.', 'languages', array['MG']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Malagasy language","url":"https://en.wikipedia.org/wiki/Malagasy_language"}]'::jsonb, '34ae8cc466bb078d265c78f639e485e1df643616796492501e3d43ae778d393b', now()),
  ('f5e3be52-2c8e-5eaa-93f8-ec9cf64ebbab', '8ef25f7d-f739-5e0f-b345-3518fa823488', 1, 'approved', 'Lingala is a major lingua franca in DR Congo and which other country?', 'Lingala is widely spoken in Kinshasa and western DR Congo and in Brazzaville, Republic of the Congo, and is popular in music.', 'languages', array['CD', 'CG']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Lingala","url":"https://en.wikipedia.org/wiki/Lingala"}]'::jsonb, '66f2cde67148bd08608a5f322e5e9349d035acb5dcdb91d4353161dd12b4e64c', now()),
  ('08522d93-ebb4-5448-94b1-c019f7a85fc1', '15f1db15-4a86-514f-8310-0331dad82aef', 1, 'approved', 'Chichewa (Nyanja) is the national language of which country?', 'Chichewa is Malawi’s national language and is also widely spoken in Zambia and Mozambique.', 'languages', array['MW']::text[], 'hard', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Chewa language","url":"https://en.wikipedia.org/wiki/Chewa_language"}]'::jsonb, 'e18387e03da5b35e69a81ecd56eb59a118038644afa69fefa5e023d21b4b6aeb', now()),
  ('eeab826d-af2d-5c82-b0d2-a43d8c388507', '5aa4da6c-096a-51ab-a148-b01e21283ac6', 1, 'approved', 'Nollywood is the film industry of which country?', 'Nollywood, Nigeria’s film industry, is one of the largest in the world by number of films made.', 'arts', array['NG']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Cinema of Nigeria","url":"https://en.wikipedia.org/wiki/Cinema_of_Nigeria"}]'::jsonb, '672d50c38c27a897ea1931f9bf8075433ceefa6235ec97bebec102a4c6620c0b', now()),
  ('5c9e9464-7f47-53b0-9287-db2eff74460c', 'a12319f9-d086-5450-b631-16b098df64d3', 1, 'approved', 'Burna Boy and Wizkid are stars of which music genre?', 'Afrobeats, a popular style from Nigeria and Ghana, made artists like Burna Boy and Wizkid global stars.', 'arts', array['NG']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Afrobeats","url":"https://en.wikipedia.org/wiki/Afrobeats"}]'::jsonb, '15f37eff1e3fe046f015aaa1e1d1d48d2c91e924dd88991c1170a4bf17955a8e', now()),
  ('fb69d153-2849-5e87-a76d-f009793effc6', '2c5a945e-0072-577e-aca5-67827a13e31a', 1, 'approved', 'Amapiano music originated in which country?', 'Amapiano emerged in South Africa’s townships, especially around Gauteng, in the mid-2010s.', 'arts', array['ZA']::text[], 'easy', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Amapiano","url":"https://en.wikipedia.org/wiki/Amapiano"}]'::jsonb, '4939b8f9027bd606e555027dcf49a89523c6c4b8c35ca02b21397cdb6bb54d56', now()),
  ('ac7bfb4b-e25e-5927-8a33-aa95ea800b12', '8b0170a2-4f20-5555-8934-d55e63498df7', 1, 'approved', 'Which Senegalese singer recorded “7 Seconds” with Neneh Cherry?', 'Youssou N’Dour and Neneh Cherry released “7 Seconds” in 1994; it became an international hit.', 'arts', array['SN']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: 7 Seconds (Youssou N''Dour song)","url":"https://en.wikipedia.org/wiki/7_Seconds_(Youssou_N%27Dour_song)"}]'::jsonb, '52d9076af3c9e311478d5d4407f31b82ed17318db29df987157a573bc0733236', now()),
  ('3ebea4b8-4818-5f29-8fb8-ea1c0ae0d428', '38a3e185-c4aa-5b5e-9a9f-0916c2321011', 1, 'approved', 'Who was the first African to win the Nobel Prize in Literature, in 1986?', 'The Nigerian playwright and poet Wole Soyinka won the Nobel Prize in Literature in 1986.', 'arts', array['NG']::text[], 'medium', 'all', array['starter-set', 'needs-review']::text[], 'en', '[{"title":"Wikipedia: Wole Soyinka","url":"https://en.wikipedia.org/wiki/Wole_Soyinka"}]'::jsonb, '4e176578577c5f8261e52da0712a849c0154fd09a6c107da9e0ad3aa4dfb07a6', now())
